     9→import Combine
    10→import Foundation
    11→import UIKit
    12→import UserNotifications
    13→
    14→final class NotificationManager: NSObject, NotificationManagerProtocol {
    15→    private let notificationCenter: UserNotificationCenterProtocol
    16→    private let appSettings: AppSettings
    17→    
    18→    private var userSession: UserSessionProtocol?
    19→    
    20→    private var cancellables = Set<AnyCancellable>()
    21→    private var notificationsEnabled = false
    22→    
    23→    init(notificationCenter: UserNotificationCenterProtocol,
    24→         appSettings: AppSettings) {
    25→        self.notificationCenter = notificationCenter
    26→        self.appSettings = appSettings
    27→        super.init()
    28→    }
    29→
    30→    // MARK: NotificationManagerProtocol
    31→
    32→    weak var delegate: NotificationManagerDelegate?
    33→    
    34→    func start() {
    35→        let replyAction = UNTextInputNotificationAction(identifier: NotificationConstants.Action.inlineReply,
    36→                                                        title: L10n.actionQuickReply,
    37→                                                        options: [])
    38→        let messageCategory = UNNotificationCategory(identifier: NotificationConstants.Category.message,
    39→                                                     actions: [replyAction],
    40→                                                     intentIdentifiers: [],
    41→                                                     options: [])
    42→        
    43→        let inviteCategory = UNNotificationCategory(identifier: NotificationConstants.Category.invite,
    44→                                                    actions: [],
    45→                                                    intentIdentifiers: [],
    46→                                                    options: [])
    47→        notificationCenter.setNotificationCategories([messageCategory, inviteCategory])
    48→        notificationCenter.delegate = self
    49→        
    50→        notificationsEnabled = appSettings.enableNotifications
    51→        MXLog.info("App setting 'enableNotifications' is '\(notificationsEnabled)'")
    52→        
    53→        // Listen for changes to AppSettings.enableNotifications
    54→        appSettings.$enableNotifications
    55→            .sink { [weak self] newValue in
    56→                self?.enableNotifications(newValue)
    57→            }
    58→            .store(in: &cancellables)
    59→        
    60→        NotificationCenter.default.publisher(for: UIApplication.didBecomeActiveNotification)
    61→            .sink { [weak self] _ in
    62→                self?.removeReceivedWhileOfflineNotification()
    63→            }
    64→            .store(in: &cancellables)
    65→    }
    66→    
    67→    func requestAuthorization() {
    68→        guard appSettings.enableNotifications, !userSession.isNil else { return }
    69→        Task {
    70→            do {
    71→                let permissionGranted = try await notificationCenter.requestAuthorization(options: [.alert, .sound, .badge])
    72→                MXLog.info("Permission granted: \(permissionGranted)")
    73→                await MainActor.run {
    74→                    if permissionGranted {
    75→                        self.delegate?.registerForRemoteNotifications()
    76→                    }
    77→                }
    78→            } catch {
    79→                MXLog.error("Request authorization failed: \(error)")
    80→            }
    81→        }
    82→    }
    83→
    84→    func register(with deviceToken: Data) async -> Bool {
    85→        guard let userSession else {
    86→            return false
    87→        }
    88→        return await setPusher(with: deviceToken, clientProxy: userSession.clientProxy)
    89→    }
    90→
    91→    func setUserSession(_ userSession: UserSessionProtocol?) {
    92→        self.userSession = userSession
    93→        
    94→        // If notification permissions were given previously then attempt re-registering
    95→        // for remote notifications on startup. Otherwise let the onboarding flow handle it
    96→        Task { [weak self] in
    97→            guard let self else { return }
    98→            
    99→            if await notificationCenter.authorizationStatus() == .authorized, appSettings.enableNotifications {
   100→                await MainActor.run { [weak self] in
   101→                    self?.delegate?.registerForRemoteNotifications()
   102→                }
   103→            }
   104→            
   105→            let settings = await notificationCenter.notificationSettings()
   106→            MXLog.info("Notification sound enabled: \(settings.soundSetting == .enabled)")
   107→        }
   108→    }
   109→
   110→    func registrationFailed(with error: Error) {
   111→        MXLog.error("Device token registration failed with error: \(error)")
   112→    }
   113→
   114→    func showLocalNotification(with title: String, subtitle: String?) async {
   115→        let content = UNMutableNotificationContent()
   116→        content.title = title
   117→        if let subtitle {
   118→            content.subtitle = subtitle
   119→        }
   120→        let request = UNNotificationRequest(identifier: ProcessInfo.processInfo.globallyUniqueString,
   121→                                            content: content,
   122→                                            trigger: nil)
   123→        do {
   124→            try await notificationCenter.add(request)
   125→            MXLog.info("Show local notification succeeded")
   126→        } catch {
   127→            MXLog.error("Show local notification failed: \(error)")
   128→        }
   129→    }
   130→    
   131→    func removeDeliveredMessageNotifications(for roomID: String) async {
   132→        let notificationsIdentifiers = await notificationCenter
   133→            .deliveredNotifications()
   134→            .filter { $0.request.content.roomID == roomID }
   135→            .map(\.request.identifier)
   136→        notificationCenter.removeDeliveredNotifications(withIdentifiers: notificationsIdentifiers)
   137→    }
   138→    
   139→    func removeDeliveredNotificationsForFullyReadRooms(_ rooms: [RoomSummary]) async {
   140→        let roomsToLastMessageDates = rooms
   141→            .filter { $0.hasUnreadMessages == false }
   142→            .reduce(into: [:]) { partialResult, roomSummary in
   143→                partialResult[roomSummary.id] = roomSummary.lastMessageDate
   144→            }
   145→        
   146→        let notificationsIdentifiers = await notificationCenter
   147→            .deliveredNotifications()
   148→            .filter { notification in
   149→                guard let roomID = notification.request.content.roomID,
   150→                      let lastMessageDate = roomsToLastMessageDates[roomID] else {
   151→                    return false
   152→                }
   153→                    
   154→                return notification.date <= lastMessageDate
   155→            }
   156→            .map(\.request.identifier)
   157→        
   158→        notificationCenter.removeDeliveredNotifications(withIdentifiers: notificationsIdentifiers)
   159→    }
   160→    
   161→    private func removeReceivedWhileOfflineNotification() {
   162→        notificationCenter.removeDeliveredNotifications(withIdentifiers: [NotificationServiceExtension.receivedWhileOfflineNotificationID])
   163→    }
   164→
   165→    private func setPusher(with deviceToken: Data, clientProxy: ClientProxyProtocol) async -> Bool {
   166→        do {
   167→            let defaultPayload = APNSPayload(aps: APSInfo(mutableContent: 1,
   168→                                                          alert: APSAlert(locKey: "Notification",
   169→                                                                          locArgs: [])),
   170→                                             pusherNotificationClientIdentifier: clientProxy.pusherNotificationClientIdentifier)
   171→
   172→            let configuration = try await PusherConfiguration(identifiers: .init(pushkey: deviceToken.base64EncodedString(),
   173→                                                                                 appId: appSettings.pusherAppID),
   174→                                                              kind: .http(data: .init(url: appSettings.pushGatewayNotifyEndpoint.absoluteString,
   175→                                                                                      format: .eventIdOnly,
   176→                                                                                      defaultPayload: defaultPayload.toJsonString())),
   177→                                                              appDisplayName: "\(InfoPlistReader.main.bundleDisplayName) (iOS)",
   178→                                                              deviceDisplayName: UIDevice.current.name,
   179→                                                              profileTag: pusherProfileTag(),
   180→                                                              lang: Bundle.app.preferredLocalizations.first ?? "en")
   181→            try await clientProxy.setPusher(with: configuration)
   182→            MXLog.info("Set pusher succeeded")
   183→            return true
   184→        } catch {
   185→            MXLog.error("Set pusher failed: \(error)")
   186→            return false
   187→        }
   188→    }
   189→
   190→    private func pusherProfileTag() -> String {
   191→        if let currentTag = appSettings.pusherProfileTag {
   192→            return currentTag
   193→        }
   194→        let chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
   195→        let newTag = (0..<16).map { _ in
   196→            let offset = Int.random(in: 0..<chars.count)
   197→            return String(chars[chars.index(chars.startIndex, offsetBy: offset)])
   198→        }.joined()
   199→
   200→        appSettings.pusherProfileTag = newTag
   201→        return newTag
   202→    }
   203→    
   204→    private func enableNotifications(_ enable: Bool) {
   205→        guard notificationsEnabled != enable else { return }
   206→        notificationsEnabled = enable
   207→        MXLog.info("App setting 'enableNotifications' changed to '\(enable)'")
   208→        if enable {
   209→            requestAuthorization()
   210→        } else {
   211→            delegate?.unregisterForRemoteNotifications()
   212→        }
   213→    }
   214→}
   215→
   216→// MARK: - UNUserNotificationCenterDelegate
   217→
   218→extension NotificationManager: UNUserNotificationCenterDelegate {
   219→    func userNotificationCenter(_ center: UNUserNotificationCenter,
   220→                                willPresent notification: UNNotification) async -> UNNotificationPresentationOptions {
   221→        guard appSettings.enableInAppNotifications else {
   222→            return []
   223→        }
   224→        guard let delegate else {
   225→            return [.badge, .sound, .list, .banner]
   226→        }
   227→
   228→        guard delegate.shouldDisplayInAppNotification(content: notification.request.content) else {
   229→            return []
   230→        }
   231→
   232→        return [.badge, .sound, .list, .banner]
   233→    }
   234→
   235→    @MainActor
   236→    func userNotificationCenter(_ center: UNUserNotificationCenter,
   237→                                didReceive response: UNNotificationResponse) async {
   238→        switch response.actionIdentifier {
   239→        case NotificationConstants.Action.inlineReply:
   240→            guard let response = response as? UNTextInputNotificationResponse else {
   241→                return
   242→            }
   243→            await delegate?.handleInlineReply(self,
   244→                                              content: response.notification.request.content,
   245→                                              replyText: response.userText)
   246→        case UNNotificationDefaultActionIdentifier:
   247→            await delegate?.notificationTapped(content: response.notification.request.content)
   248→        default:
   249→            break
   250→        }
   251→    }
   252→}
   253→
   254→extension UNUserNotificationCenter: UserNotificationCenterProtocol { }
