   161→    func pushRegistry(_ registry: PKPushRegistry, didReceiveIncomingPushWith payload: PKPushPayload, for type: PKPushType, completion: @escaping () -> Void) {
   162→        guard let roomID = payload.dictionaryPayload[ElementCallServiceNotificationKey.roomID.rawValue] as? String else {
   163→            MXLog.error("Something went wrong, missing room identifier for incoming voip call: \(payload)")
   164→            completion()
   165→            return
   166→        }
   167→        
   168→        guard let rtcNotificationID = payload.dictionaryPayload[ElementCallServiceNotificationKey.rtcNotifyEventID.rawValue] as? String else {
   169→            MXLog.error("Something went wrong, missing rtc notification event identifier for incoming voip call: \(payload)")
   170→            completion()
   171→            return
   172→        }
   173→        
   174→        guard ongoingCallID?.roomID != roomID else {
   175→            MXLog.warning("Call already ongoing for room \(roomID), ignoring incoming push")
   176→            completion()
   177→            return
   178→        }
   179→        
   180→        let callID = CallID(callKitID: UUID(), roomID: roomID, rtcNotificationID: rtcNotificationID)
   181→        incomingCallID = callID
   182→        
   183→        guard let expirationDate = (payload.dictionaryPayload[ElementCallServiceNotificationKey.expirationDate.rawValue] as? Date) else {
   184→            MXLog.error("Something went wrong, missing expiration timestamp for incoming voip call: \(payload)")
   185→            completion()
   186→            return
   187→        }
   188→        
   189→        let nowDate = timeProvider.now()
   190→        
   191→        guard nowDate < expirationDate else {
   192→            MXLog.warning("Call expired for room \(roomID), ignoring incoming push")
   193→            completion()
   194→            return
   195→        }
   196→        
   197→        let ringDuration: Duration = .seconds(min(expirationDate.timeIntervalSince1970 - nowDate.timeIntervalSince1970, 90))
   198→        
   199→        let roomDisplayName = payload.dictionaryPayload[ElementCallServiceNotificationKey.roomDisplayName.rawValue] as? String
   200→        
   201→        let update = CXCallUpdate()
   202→        update.hasVideo = true
   203→        update.localizedCallerName = roomDisplayName
   204→        // https://stackoverflow.com/a/41230020/730924
   205→        update.remoteHandle = .init(type: .generic, value: roomID)
   206→        
   207→        callProvider.reportNewIncomingCall(with: callID.callKitID, update: update) { [weak self] error in
   208→            if let error {
   209→                MXLog.error("Failed reporting new incoming call with error: \(error)")
   210→            }
   211→            
   212→            self?.actionsSubject.send(.receivedIncomingCallRequest)
   213→            
   214→            completion()
   215→        }
   216→        
   217→        endUnansweredCallTask = Task { [weak self] in
   218→            try? await self?.timeProvider.clock.sleep(for: ringDuration)
   219→            
   220→            guard let self, !Task.isCancelled else {
   221→                return
   222→            }
   223→            
   224→            if let incomingCallID, incomingCallID.callKitID == callID.callKitID {
   225→                callProvider.reportCall(with: incomingCallID.callKitID, endedAt: nil, reason: .unanswered)
   226→            }
   227→        }
   228→    }
